import{_ as r,H as o,c as i,b as s,a2 as a,K as n}from"./chunks/framework.BEqfOpL-.js";const l="/images/pr_outreach.webp",y=JSON.parse('{"title":"PR Outreach","description":"PR Outreach provides a Kanban-style CRM for tracking your podcast promotion efforts. Manage pitch targets, track follow-ups, and move opportunities through your pipeline from initial contact to successful feature.","frontmatter":{},"headers":[],"relativePath":"features/pr-outreach.md","filePath":"features/pr-outreach.md"}'),d={name:"features/pr-outreach.md"};function u(c,e,h,p,g,f){const t=o("HelpWalkthrough");return s(),i("div",null,[e[0]||(e[0]=a('<h1 id="pr-outreach" tabindex="-1">PR Outreach <a class="header-anchor" href="#pr-outreach" aria-label="Permalink to &quot;PR Outreach&quot;">​</a></h1><h2 id="manage-your-podcast-pitch-pipeline" tabindex="-1">Manage Your Podcast Pitch Pipeline <a class="header-anchor" href="#manage-your-podcast-pitch-pipeline" aria-label="Permalink to &quot;Manage Your Podcast Pitch Pipeline&quot;">​</a></h2><p>PR Outreach provides a Kanban-style CRM for tracking your podcast promotion efforts. Manage pitch targets, track follow-ups, and move opportunities through your pipeline from initial contact to successful feature.</p><p><a href="/images/pr_outreach.webp" title="Open screenshot at full size"><img src="'+l+'" alt="PR Outreach Pipeline" width="600px" style="display:block;margin:0 auto;"></a></p><p><strong>To access:</strong> <strong>Promote → PR Outreach</strong> in the sidebar. The page opens on the <strong>Pipeline</strong> tab; <strong>Curated lists</strong> and <strong>Placements</strong> are the other two tabs.</p><h2 id="your-outreach-pipeline" tabindex="-1">Your Outreach Pipeline <a class="header-anchor" href="#your-outreach-pipeline" aria-label="Permalink to &quot;Your Outreach Pipeline&quot;">​</a></h2><p>The pipeline organizes your outreach efforts into five stages:</p><h3 id="identified" tabindex="-1">Identified <a class="header-anchor" href="#identified" aria-label="Permalink to &quot;Identified&quot;">​</a></h3><p>Targets you&#39;ve discovered but haven&#39;t contacted yet. These are opportunities waiting for your first pitch — editorial contacts, newsletter curators, podcast directories, or media outlets.</p><h3 id="contacted" tabindex="-1">Contacted <a class="header-anchor" href="#contacted" aria-label="Permalink to &quot;Contacted&quot;">​</a></h3><p>Pitches you&#39;ve sent that are awaiting response. When you move a card here, PodSEO records the pitch date automatically.</p><h3 id="replied" tabindex="-1">Replied <a class="header-anchor" href="#replied" aria-label="Permalink to &quot;Replied&quot;">​</a></h3><p>Active conversations where you&#39;ve received a response. These are warm leads that need nurturing toward a feature.</p><h3 id="featured" tabindex="-1">Featured <a class="header-anchor" href="#featured" aria-label="Permalink to &quot;Featured&quot;">​</a></h3><p>Success! Targets that have featured your podcast. The feature date is recorded automatically when you move a card here.</p><h3 id="declined" tabindex="-1">Declined <a class="header-anchor" href="#declined" aria-label="Permalink to &quot;Declined&quot;">​</a></h3><p>Opportunities that didn&#39;t work out. Keeping these helps you track conversion rates and learn from what didn&#39;t resonate.</p><h2 id="pipeline-features" tabindex="-1">Pipeline Features <a class="header-anchor" href="#pipeline-features" aria-label="Permalink to &quot;Pipeline Features&quot;">​</a></h2><h3 id="summary-dashboard" tabindex="-1">Summary Dashboard <a class="header-anchor" href="#summary-dashboard" aria-label="Permalink to &quot;Summary Dashboard&quot;">​</a></h3><p>At the top, a funnel summarizes your progress across four key stages at a glance:</p><ul><li><strong>Identified</strong> - How many targets are ready to pitch</li><li><strong>Contacted</strong> - Active outreach awaiting responses</li><li><strong>Replied</strong> - Conversations in progress</li><li><strong>Featured</strong> - Successful features achieved</li></ul><p>The funnel focuses on these four stages. Declined still appears as its own column on the board below, so you can keep a record of opportunities that didn&#39;t work out, but it isn&#39;t part of the funnel summary.</p><h3 id="overdue-follow-ups" tabindex="-1">Overdue Follow-ups <a class="header-anchor" href="#overdue-follow-ups" aria-label="Permalink to &quot;Overdue Follow-ups&quot;">​</a></h3><p>An alert appears when you have follow-ups past their scheduled date. Timely follow-ups are crucial for successful outreach - don&#39;t let opportunities go cold.</p><h3 id="target-cards" tabindex="-1">Target Cards <a class="header-anchor" href="#target-cards" aria-label="Permalink to &quot;Target Cards&quot;">​</a></h3><p>Each pipeline card shows:</p><ul><li>Target name and domain</li><li>Current status</li><li>Any notes you&#39;ve added</li><li>Scheduled follow-up date</li></ul><h3 id="drag-and-drop-management" tabindex="-1">Drag-and-Drop Management <a class="header-anchor" href="#drag-and-drop-management" aria-label="Permalink to &quot;Drag-and-Drop Management&quot;">​</a></h3><p>Move targets between columns as your relationship progresses. Drag a card from &quot;Contacted&quot; to &quot;Replied&quot; when you get a response, or to &quot;Featured&quot; when you achieve success.</p><h2 id="managing-your-targets" tabindex="-1">Managing Your Targets <a class="header-anchor" href="#managing-your-targets" aria-label="Permalink to &quot;Managing Your Targets&quot;">​</a></h2><h3 id="adding-targets" tabindex="-1">Adding Targets <a class="header-anchor" href="#adding-targets" aria-label="Permalink to &quot;Adding Targets&quot;">​</a></h3><p>Two ways to add pitch targets:</p><p><strong>Add Custom Target</strong> - Create your own entry for any newsletter, blog, editor, or award submission you want to pitch. The form asks for:</p><ul><li><strong>Target name</strong> (required) - The person or publication</li><li><strong>Website URL</strong></li><li><strong>Description</strong> - A brief note on what this target is</li><li><strong>Contact name</strong>, <strong>Email</strong>, and <strong>Twitter handle</strong></li><li><strong>Submission page</strong> - The URL where you submit your pitch</li></ul><p>Once the card is created, open it to add notes about the opportunity.</p><p><strong>Find Opportunities</strong> - Opens a panel with PodSEO&#39;s curated list of pitch targets for editorial, award, and featured placement consideration. This includes platform editorial submission pages (such as <strong>Apple Podcasts Editorial</strong> and <strong>Spotify Editorial</strong>) alongside podcast newsletters, directories, blogs, and curated recommendation sites worth pitching — for example, Goodpods, EarBuds Podcast Collective, and All Hear. Click <strong>Add</strong> on any opportunity to create a card in your Identified column. Each opportunity includes a description and, where available, the submission or contact link you&#39;ll need to pitch your podcast.</p><h3 id="target-details" tabindex="-1">Target Details <a class="header-anchor" href="#target-details" aria-label="Permalink to &quot;Target Details&quot;">​</a></h3><p>Open a target card to inspect its available contact and submission links. Add <strong>Notes</strong> about the pitch, set a <strong>Follow-up reminder</strong>, and choose the <strong>Current status</strong> that matches what actually happened. Notes save when you leave the field. The details also show when the target was added, pitched and featured.</p>',38)),n(t,{src:"/walkthroughs/pr-follow-up.webp",poster:"/images/pr_outreach.webp",alt:"Save a target note and follow-up date, move the card to Contacted and reopen it to review the saved details",duration:30150,autoplay:"",loop:"",sample:""}),e[1]||(e[1]=a('<p>Move a card to <strong>Contacted</strong> after sending your pitch yourself. Changing its status records progress; it does not send an email. The follow-up date helps you keep track of the next action.</p><h3 id="daily-follow-up-email" tabindex="-1">Daily Follow-up Email <a class="header-anchor" href="#daily-follow-up-email" aria-label="Permalink to &quot;Daily Follow-up Email&quot;">​</a></h3><p>On days when you have follow-ups that are overdue or due that day, PodSEO sends you a single daily digest email listing them, split into overdue and due-today items, with a link back to your pipeline. You won&#39;t get the email on days with nothing due. The digest respects your email preferences, so if you&#39;ve opted out of PodSEO emails you won&#39;t receive it.</p><h2 id="outreach-best-practices" tabindex="-1">Outreach Best Practices <a class="header-anchor" href="#outreach-best-practices" aria-label="Permalink to &quot;Outreach Best Practices&quot;">​</a></h2><h3 id="building-your-pipeline" tabindex="-1">Building Your Pipeline <a class="header-anchor" href="#building-your-pipeline" aria-label="Permalink to &quot;Building Your Pipeline&quot;">​</a></h3><ul><li><strong>Start with research</strong> - Identify publications, newsletters, and platforms that feature podcasts like yours</li><li><strong>Quality over quantity</strong> - Focus on relevant targets rather than mass outreach</li><li><strong>Mix target types</strong> - Include editorial contacts, newsletter curators, and industry publications</li></ul><h3 id="effective-pitching" tabindex="-1">Effective Pitching <a class="header-anchor" href="#effective-pitching" aria-label="Permalink to &quot;Effective Pitching&quot;">​</a></h3><ul><li><strong>Personalize each pitch</strong> - Reference specific content or explain why you&#39;re a good fit</li><li><strong>Be concise</strong> - Busy editors appreciate brief, clear pitches</li><li><strong>Include value</strong> - Explain what&#39;s in it for their audience</li><li><strong>Make it easy</strong> - Provide assets, links, and everything they need</li></ul><h3 id="following-up" tabindex="-1">Following Up <a class="header-anchor" href="#following-up" aria-label="Permalink to &quot;Following Up&quot;">​</a></h3><ul><li><strong>Schedule systematically</strong> - Set follow-up dates for every contact</li><li><strong>Be persistent but respectful</strong> - 2-3 follow-ups is appropriate</li><li><strong>Add value each time</strong> - Share news, new episodes, or relevant angles</li><li><strong>Know when to move on</strong> - Not every pitch will convert</li></ul><h3 id="learning-from-success" tabindex="-1">Learning from Success <a class="header-anchor" href="#learning-from-success" aria-label="Permalink to &quot;Learning from Success&quot;">​</a></h3><p>Track what works in your Featured column:</p><ul><li>Which pitch angles resonated</li><li>What types of targets converted</li><li>Timing patterns that worked</li><li>Content that attracted features</li></ul><h2 id="integration-with-my-placements" tabindex="-1">Integration with My Placements <a class="header-anchor" href="#integration-with-my-placements" aria-label="Permalink to &quot;Integration with My Placements&quot;">​</a></h2><p>PR Outreach helps you actively pursue features, while <a href="/features/my-placements.html">My Placements</a> tracks where features appear. Together they give you a complete picture of your editorial visibility efforts and results.</p><h2 id="pr-outreach-and-ai-visibility" tabindex="-1">PR Outreach and AI Visibility <a class="header-anchor" href="#pr-outreach-and-ai-visibility" aria-label="Permalink to &quot;PR Outreach and AI Visibility&quot;">​</a></h2><p>A relevant newsletter, review site, or podcast roundup can introduce your show to new readers. Some web pages are also cited by AI assistants. In <a href="/features/ai-mentions.html">AI Mentions</a>, inspect cited sources and save a relevant page to your outreach pipeline. A placement does not guarantee that an assistant will recommend your podcast.</p><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>PR Outreach is available on paid plans (Podcaster, Producer, and Agency). The pipeline helps you systematically grow your podcast&#39;s media presence.</p><p><strong>Related Features</strong>: Check <a href="/features/my-placements.html">My Placements</a> to see where your podcast has been featured, use <a href="/features/curated-lists.html">Curated Lists</a> to research editorial opportunities, and track the payoff in <a href="/features/ai-mentions.html">AI Mentions</a> as web recommendations feed AI discovery.</p>',20))])}const b=r(d,[["render",u]]);export{y as __pageData,b as default};
